"""Content data: ai-product (part 1 of 2) — start-here, product-strategy, user-research, mock, capstone, labs 1-5."""
from cbt_builder import L, S, LB, D, start_here_domain, mock_domain, capstone_domain
from cbt_data_aiprod2 import build_aiprod2
CN = 'AI Product'

def build_aiprod():
    new_domains = []
    labs = []
    new_domains.append(start_here_domain(CN, 'assessment', 'LLM APIs'))

    def std(did, name, desc, lesson_specs, scen_specs, icon=None):
        lessons = [L(did, *sp) for sp in lesson_specs]
        scenarios = [S(did, *sp) for sp in scen_specs]
        new_domains.append(D(did, name, desc, lessons, scenarios, icon=icon))
    did = 'product-strategy'
    (std(did, 'AI Product Strategy', 'Frame the right problems, choose defensible wedges, and make build-vs-buy decisions that survive contact with real users and real costs.', [('Problem Framing: AI Is Not the Product', ["Start from the job-to-be-done, not the model: 'reduce support handle time' is a product; 'an LLM chatbot' is a technology looking for a problem", 'The AI value test: does intelligence change the outcome 10x versus rules or search? If a regex solves it, ship the regex — AI is expensive, slow, and non-deterministic', 'Map the workflow before the model: where does a human currently decide, and is that decision frequent, painful, and data-rich enough to automate?', 'Write the press release first (working backwards): the future headline forces you to name the customer, the pain, and the measurable win'], 'Framing canvas:\n  CUSTOMER: support leads at 200-seat SaaS companies\n  JOB: resolve repetitive tickets without hiring\n  TODAY: macros + copy-paste, 12 min/ticket\n  AI WIN: draft answers from knowledge base, 4 min/ticket\n  10x TEST: yes — language understanding is the bottleneck', "The most common AI product failure is a solution in search of a problem: a demo that wows and a product nobody buys. If you cannot name the workflow, the pain's dollar cost, and why rules fail, you do not have a product yet — you have a demo.", ['Leading with model capabilities instead of customer pain', 'Automating a workflow nobody does frequently enough to matter', "Skipping the 10x test — marginal gains do not justify AI's cost and risk"], 'Take one AI feature idea and run the framing canvas: customer, job, today-state, AI win, 10x test.'), ('Defensibility: Your Moat in the AI Era', ["Models are commoditizing: today's frontier advantage is next year's API price cut — moats must live elsewhere", 'Data moats: proprietary feedback loops (every user correction improves YOUR model), exclusive data access, and workflow-embedded context competitors cannot scrape', 'Distribution moats: embedded in the workflow (the copilot inside the tool they already open), network effects, and switching costs from integrations', "Execution moats: evals, domain-tuned reliability, and operational excellence — 'it actually works in production' is a moat most AI startups lack"], 'Moat audit:\n  Model: parity in 12 months (not a moat)\n  Data: 2M labeled support resolutions (moat)\n  Distribution: embedded in helpdesk (moat)\n  Reliability: 99.2% grounded answers (moat)\n\nInvest where the moat compounds.', "Ask the uncomfortable question: if a frontier lab shipped your exact feature tomorrow, what would keep your customers? If the honest answer is 'nothing,' your roadmap's first job is building the answer — usually data, distribution, or reliability depth.", ['Believing the model choice is the moat', 'Collecting data with no plan to convert it into a feedback loop', 'Ignoring distribution — best model loses to best-distributed product'], 'Run the moat audit on an AI product you know: what survives a frontier lab shipping the same feature?'), ('Build vs Buy vs Wrap', ['Buy (API): fastest to market, zero infra burden — right when the model is not your differentiator and latency/cost fit', 'Build (fine-tune/self-host): justified when you need data privacy, cost at scale, latency control, or behavior the APIs cannot produce', "Wrap honestly: a thin UX over an API is a valid product IF the value is in workflow, distribution, or data — invalid if the pitch is 'better AI'", 'The hybrid default: buy the foundation model, build the retrieval, evals, UX, and feedback loops — that is where most AI product value actually lives'], 'Decision matrix:\n  Differentiator = model behavior? -> consider fine-tune\n  Differentiator = workflow/data? -> buy model, build the rest\n  Volume > 10M queries/mo? -> price self-host vs API\n  Regulated data? -> self-host or VPC deployment\n\nDefault: buy foundation, build product.', 'Revisit the decision every 6 months: API prices fall, open models improve, and your volume changes the math. The build-vs-buy answer has an expiry date — calendar the review.', ['Fine-tuning before proving the product works with prompting + RAG', "Self-hosting for 'control' at 10k queries a month — negative ROI", 'Never revisiting the decision as prices and volumes move'], 'Score one AI feature on the decision matrix: buy, build, or hybrid? Write the one-paragraph justification.'), ('Roadmapping Under Model Uncertainty', ['Model capabilities shift quarterly: roadmap in bets with 90-day horizons for model-dependent features, longer for workflow and data investments', 'Capability insurance: design features so a better model improves them automatically (better retrieval, cleaner evals) rather than requiring rebuilds', "Two-track roadmap: track one exploits today's models (ship now), track two prepares for next-gen capabilities (data pipelines, evals, UX patterns)", "Kill criteria up front: define what 'the model got good enough to obsolete this' looks like, so you pivot deliberately instead of defensively"], 'Roadmap format:\n  NOW (ship): prompt-based features on current models\n  NEXT (build): eval harness, feedback loops, data pipelines\n  LATER (bet): agent workflows when reliability crosses 95%\n  KILL IF: frontier model ships native support for X\n\nEvery bet carries its kill condition.', "The roadmap is a portfolio, not a promise: model-dependent bets are options, and options need expiry dates. Review quarterly against actual model releases — the labs' changelogs are your roadmap's weather report.", ["12-month roadmaps assuming today's model capabilities", 'Building elaborate scaffolding around a weakness the next model release fixes', 'No kill criteria — zombie features nobody will retire'], 'Write kill criteria for two model-dependent features on a roadmap you know.'), ('Pricing the AI Value: Capturing What You Create', ['AI products create value in strange shapes: time saved, errors avoided, capacity unlocked — price the outcome the buyer feels, not the tokens you burn', 'The value conversation happens before the pricing page: discovery must surface the dollar cost of the pain, or every price feels expensive', "Anchor on the alternative: the buyer's comparison is not your competitor — it is hiring, outsourcing, or living with the pain — price against THAT", 'Leave money on the table deliberately at first: early pricing buys learning and logos; you can raise prices on proven value, but you cannot un-churn sticker shock'], 'Value pricing worksheet:\n  Pain: 500 tickets/mo x 12 min x $45/hr loaded = $4,500/mo\n  AI resolves 60% -> $2,700/mo value\n  Price at 20-30% of value: $540-810/mo\n  Buyer ROI: 3-5x. Your margin: 80%.\n\nPrice the pain, not the tokens.', "If you cannot articulate the buyer's ROI in one sentence, you are not ready to price — go back to discovery. Pricing without a value story is just a number waiting to be negotiated down.", ['Cost-plus pricing on tokens — races to the bottom as models get cheaper', "Pricing before quantifying the buyer's pain", 'Optimizing early pricing for margin instead of learning'], 'Write the one-sentence ROI story for an AI feature: whose pain, what dollar value, what price?')], [('aiprod-strat-regex', 'The Regex Test', 'Your team proposes an LLM to categorize incoming support emails into 12 fixed categories. A rules-based classifier already hits 88% accuracy on the same task.', 'What is the right product call?', ['Ship the rules classifier and spend the AI budget where language understanding is the actual bottleneck. The LLM adds cost, latency, and non-determinism for marginal gain on a solved problem.', 'Use the LLM — it is more modern and impressive.', 'Use the LLM but hide the cost in the platform fee.', 'Build both and A/B test for six months.'], 0, "The correct approach applies the AI value test: when rules already solve the problem at 88%, the LLM's marginal accuracy rarely justifies its cost, latency, and failure modes. AI budget is finite — spend it where intelligence is the bottleneck, not where it is decoration.", 'What does the LLM buy you that the 88% classifier does not?', ['Apply the AI value test', 'Avoid AI-for-decoration', 'Allocate AI budget to bottlenecks'], 10, [['Baseline', 'Rules classifier: 88% accuracy, $0 marginal cost, deterministic']]), ('aiprod-strat-moat', 'The Frontier Lab Ships Your Feature', "A frontier AI lab just released your startup's headline feature as a native capability. Your board asks what keeps customers.", 'What is the honest strategic answer?', ['Cut prices to retain customers.', 'Name the non-model moats: your labeled feedback data, workflow embedding, integrations, and reliability track record — then double investment in the moat that compounds fastest (usually the data flywheel).', 'Pivot immediately to a new feature.', 'Claim your implementation is still better.'], 1, 'The correct approach treats the event as the moat audit made real: models commoditize on schedule, so survival was always about data, distribution, and execution depth. The response is investment in compounding advantages, not panic pivots or price wars.', 'What do you own that the lab cannot ship overnight?', ['Audit defensibility honestly', 'Invest in compounding moats', 'Respond to commoditization'], 15, [['Competitive event', 'Headline feature now native in the frontier model; 40% of pipeline mentions it']]), ('aiprod-strat-buildbuy', 'The Fine-Tune Temptation', "Your RAG support bot works well with prompting. An engineer proposes fine-tuning 'to make it truly ours' — 3 months of work, ongoing training infra.", 'How do you decide?', ['Reject it — never fine-tune.', 'Let the engineer decide; it is a technical call.', 'Demand the evidence: does prompting + better retrieval + evals close the gap first? Fine-tune only when you can name the behavior APIs cannot produce (tone, privacy, latency, cost at scale) and the ROI clears the 3-month investment.', 'Approve it — owning the model is strategic.'], 2, "The correct approach sequences the cheap wins first: most 'needs fine-tuning' gaps are retrieval quality, prompt design, or eval blind spots. Fine-tuning is justified by specific, measurable, otherwise-unreachable behavior — not by ownership aesthetics.", 'What behavior can ONLY fine-tuning produce here?', ['Sequence AI investments by ROI', 'Require evidence before fine-tuning', 'Treat build-vs-buy as economics'], 10, [['Proposal', '3-month fine-tune project; current RAG at 91% grounded answers']]), ('aiprod-strat-roadmap', 'The Obsoleted Quarter', "Your team spent a quarter building elaborate prompt scaffolding around a model's weak reasoning. The new model release fixes the weakness natively. The work is now dead code.", 'What roadmap discipline prevents repeats?', ["Stop building on other companies' models.", 'Build everything as if models never improve.', 'It was unavoidable; move on.', "Capability insurance plus kill criteria: design model-dependent work as thin adapters, define 'the model fixed it' as an explicit kill condition, and review the roadmap against model changelogs quarterly."], 3, 'The correct approach accepts model progress as weather, not betrayal: thin adapters, explicit kill criteria, and quarterly changelog reviews turn obsolescence from a surprise into a planned harvest — you delete the scaffolding and keep the evals, data, and UX.', 'Which parts of the work survive the model getting better?', ['Design for model progress', 'Set kill criteria on bets', 'Review roadmaps against changelogs'], 10, [['Post-mortem', 'Quarter of scaffolding work obsoleted by one model release']]), ('aiprod-strat-press', 'The Demo That Wows', 'Your AI demo consistently wows prospects, but pilots stall: users cannot describe what job it does, and nobody can name the metric it moves.', 'What is missing?', ["Problem framing: the demo sells capability, not an outcome. Work backwards from the press release — name the customer, the workflow, the pain's cost, and the metric — then rebuild the pilot around that job-to-be-done.", 'A better demo with more impressive examples.', 'More features to cover more use cases.', 'Lower pilot pricing to reduce friction.'], 0, "The correct approach diagnoses 'wow without buy' as a framing failure: capability demos create excitement without urgency. Anchoring on a specific workflow with a dollar-valued pain converts admiration into budget.", 'What does the buyer tell their boss this purchase achieves?', ['Frame AI products on jobs-to-be-done', 'Work backwards from outcomes', 'Convert demos into pilots'], 10, [['Pilot data', "12 pilots started, 1 converted; 'impressive but unclear fit' in exit notes"]]), ('aiprod-strat-data', 'The Unused Data Asset', 'Your product logs 2 million user corrections a year. They sit in cold storage. A competitor just launched with noticeably better accuracy in your category.', 'What is the strategic move?', ['Delete the logs to reduce storage cost.', 'Activate the feedback flywheel: build the pipeline from corrections → labeled data → eval improvements → model updates, with consent and PII handling. Your logged corrections are the moat — but only if they compound.', 'Buy a third-party dataset to catch up.', 'It is too late; the competitor won.'], 1, "The correct approach treats accumulated corrections as an unrefined moat: the competitor's edge likely came from exactly this loop. Building the correction-to-improvement pipeline converts a cost center (storage) into the compounding advantage.", 'What is the half-life of your current accuracy lead without the loop?', ['Build data feedback flywheels', 'Convert corrections into moats', 'Treat logged data as strategy'], 15, [['Asset', '2M user corrections/year in cold storage; competitor accuracy +6pts']]), ('aiprod-strat-pilot', 'The Pilot That Never Converts', "Your AI pilot at a mid-market company is a clear success: 55% ticket deflection, agents love it, the champion is enthusiastic. Six months later, still no paid contract — 'procurement is reviewing.'", 'What went wrong in the product strategy?', ['The champion is weak; find a new one.', 'Pilots never convert; focus on self-serve only.', 'The pilot proved value to users but never built the enterprise buying case: no economic buyer engaged, no ROI document for finance, no security review started. Successful pilots convert when the buying process runs in parallel with the technical win.', 'The product is not good enough; improve deflection to 80%.'], 2, "The correct approach treats the pilot as a sales process, not just a technical trial: multi-thread to the economic buyer early, arm the champion with ROI math, and start security review in week two — not after 'success.' User love without a buying path is a free trial with extra steps.", 'Who signs the contract, and what do THEY need that the pilot never produced?', ['Run buying process parallel to pilots', 'Multi-thread to economic buyers', 'Arm champions with ROI evidence'], 10, [['Pilot', "6 months, 55% deflection, champion enthusiastic, no contract, procurement 'reviewing'"]]), ('aiprod-strat-platform', 'The Platform Temptation', "Your focused AI support product is winning. Investors push you to 'become the AI platform for all customer operations' — a bigger story, a bigger round.", 'What is the disciplined strategic response?', ['Take the bigger story and raise on the platform vision.', 'Build the platform quietly while selling the point product.', 'Reject all expansion forever; stay tiny.', 'Stay focused until the wedge is undeniable: platforms are built from successful products, not declared. Expand to adjacent jobs only when the core has retention, expansion revenue, and a repeatable sale — otherwise you trade a winning position for a losing breadth.'], 3, 'The correct approach sequences ambition: depth before breadth. A platform narrative without a dominant wedge is a story investors fund and customers ignore. Earn the right to expand with metrics — NRR, repeatability, pull from adjacent teams — then expand into proven adjacency.', 'What evidence says you have earned the right to expand?', ['Sequence depth before breadth', 'Resist premature platforming', 'Expand on evidence, not narrative'], 10, [['Board pressure', "'Platform' narrative requested; core product NRR 124%, 40 customers"]])], icon='🧭'),)
    did = 'user-research'
    (std(did, 'User Research for AI Products', 'Discover real AI jobs-to-be-done, test with prototypes before models, and measure what users actually do — not what they say about AI.', [('Discovering AI Jobs-to-Be-Done', ['Watch the work, not the wishlist: shadow users doing the task today and log where they hesitate, copy-paste, or ask a colleague — those are the automation seams', "Ask about the last time, not the hypothetical: 'walk me through the last ticket you escalated' beats 'would you use an AI that...' — stated preference for AI is wildly inflated", 'Quantify the pain before building: frequency × duration × error cost. A daily 20-minute pain outranks a monthly 2-hour pain for AI products (habit formation needs repetition)', 'Segment by AI-readiness: some users want autopilot, others want a copilot, some want nothing automated — one product can serve all three with modes, but research must find the split'], 'Interview guide (30 min):\n  1. Last time you did [task]? Walk me through it.\n  2. Where did you get stuck or annoyed?\n  3. What did you do about it? (workaround = real pain)\n  4. If this took 10 seconds, what would you do with the time?\n\nWorkarounds reveal willingness to pay.', "Recruit outside the AI-enthusiast bubble: your early volunteers overstate comfort with automation. The skeptical veteran who has seen three 'AI' tools fail is your most valuable interview — they describe the trust bar you must clear.", ["Asking 'would you use an AI for this?' — everyone says yes, nobody means it", 'Interviewing only enthusiasts — the trust bar looks lower than it is', 'Skipping quantification — unmeasured pain cannot prioritize a roadmap'], "Write 4 'last time' interview questions for one workflow you want to automate."), ('Wizard-of-Oz Testing for AI', ["Test the experience before the model: a human behind the curtain produces the 'AI' output, letting you validate desirability and UX in days instead of model-months", 'Fake the right layer: the wizard must produce realistic output quality — including realistic ERRORS — or you will validate a fantasy', 'Measure what matters: task completion, time saved, trust behaviors (did they verify? did they edit?), and the correction rate your pipeline must handle', "Debrief honestly: reveal the wizard, then ask what would change if it were instant, dumber, or wrong 10% of the time — you are testing the concept's robustness, not the demo"], "WOZ protocol:\n  Day 1-2: script the wizard's responses + error rate (e.g., 85% good)\n  Day 3-5: 8 users, real tasks, wizard in another room\n  Metrics: completion, time, edits, trust checks\n  Debrief: reveal + 'what if it were wrong 1 in 10?'\n\nKill or commit in one week.", "The wizard's error rate is the most important parameter: testing with a perfect wizard validates a product you cannot build. Set the error rate to your realistic model target and watch whether users still get value — that is the real test.", ['Wizard too perfect — validating an unbuildable product', 'Never debriefing — users feel deceived when they find out later', 'Testing UI polish instead of the core value exchange'], 'Design a 1-week Wizard-of-Oz test for one AI feature: wizard script, error rate, metrics, debrief questions.'), ('Mental Models: What Users Believe the AI Is', ['Users arrive with a mental model — intern, oracle, search engine, colleague — and it dictates how they prompt, what they trust, and how they react to errors', "Mismatched models cause the failure modes: the 'oracle' user never verifies; the 'intern' user over-verifies and gets no leverage; the 'search' user writes keywords instead of tasks", "Shape the model deliberately: onboarding copy, example prompts, and the UI's language ('draft,' 'suggest,' 'suggestion') teach users what the system is", 'Test comprehension, not satisfaction: ask users to predict what the AI will do in a new situation — accurate predictions mean the mental model is right'], "Model-shaping copy:\n  Oracle framing: 'Ask anything, get answers' -> overtrust\n  Copilot framing: 'Drafts for you to review' -> calibrated\n  Tool framing: 'Summarize, extract, draft' -> task-shaped prompts\n\nEvery word teaches the model.", "Revisit mental models after errors: a single confident hallucination can flip a user from 'copilot' to 'untrustworthy toy' permanently. The recovery UX — acknowledgment, correction, explanation — is where the model gets rebuilt.", ["Letting marketing write 'AI that knows everything' while the product needs verification", 'Measuring NPS instead of model accuracy — satisfaction hides misunderstanding', 'One mental model for all users — novices and experts need different framing'], "Write three onboarding sentences that teach the 'draft for review' mental model for an AI feature."), ('Measuring AI Product-Market Fit', ["The AI PMF question is not 'do they like it' but 'does it change behavior': retention of activated users, frequency of the core AI action, and corrections trending down", "Sean Ellis test, AI edition: 'how disappointed if this AI feature disappeared?' — 40%+ 'very disappointed' still applies, but segment by heavy vs light users", 'Leading indicators: correction/edit rates falling, prompt sophistication rising, sharing of outputs, expansion to new use cases unprompted', 'Cohort the truth: AI products often show great week-1 novelty then decay — measure 8-week retained behavior, not launch-week excitement'], "AI PMF scorecard:\n  8-wk retention of activated: ___% (target 40%+)\n  Core AI actions / user / week: ___ (rising?)\n  Correction rate trend: ___ (falling?)\n  'Very disappointed': ___% (target 40%+)\n  Unprompted expansion: ___ cases\n\nBehavior over attitudes.", 'Beware the novelty curve: AI demos produce a dopamine spike that looks like PMF for 2-3 weeks. Make every PMF claim from cohorts past week 8, and distrust any metric that peaks at launch.', ['Declaring PMF from launch-week engagement', 'Tracking logins instead of the core AI action', 'Averaging heavy and light users — the segments tell different stories'], 'Draft the AI PMF scorecard for a product you know: fill what you can, mark what you would instrument.'), ('Researching Trust Over Time', ['Trust in AI is longitudinal: first impressions form in minutes, but durable trust builds (or erodes) over weeks of observed behavior — one-shot studies miss the curve', 'Diary studies reveal the trust trajectory: ask users to log AI interactions for 2-4 weeks — you will see the honeymoon, the first betrayal, and the new equilibrium', 'The betrayal moment is the richest data: when the AI fails a user, what do they do — abandon, work around, or forgive? The recovery design decides which', 'Re-research after errors ship: every major AI failure is a natural experiment — interview affected users within days, while the memory is fresh'], "Longitudinal protocol:\n  Week 1: baseline mental model interview\n  Weeks 2-3: diary (log each AI use: task, result, trust 1-5)\n  Week 4: betrayal interview ('tell me about a time it failed')\n  Analysis: plot trust over time; find the inflection points\n\nTrust is a time series, not a snapshot.", 'Do not only study your successes: recruit users who churned or reduced usage — the ex-user interview is where the trust failures live. Current users have survivorship bias baked in.', ['One-shot usability tests as the only trust research', 'Studying only happy, retained users', 'Never re-interviewing after a shipped failure'], 'Design a 4-week diary study for one AI feature: what gets logged, and what inflection points do you expect?')], [('aiprod-research-wishlist', 'The Enthusiastic Yes', "In interviews, 9 of 10 users say they would 'love an AI that writes my reports.' You build it. Adoption is near zero.", 'What went wrong in the research?', ["Stated-preference trap: 'would you use it' measures politeness, not demand. The interviews never observed the actual workflow, quantified the pain, or tested with a prototype — so you built for imagined desire.", 'The AI quality was not good enough.', 'Users lied deliberately.', 'Report writing is not automatable.'], 0, 'The correct approach replaces hypothetical questions with observed behavior: shadowing the last real report-writing session, quantifying the pain, and Wizard-of-Oz testing the concept before model work. Enthusiasm in interviews is cheap; changed behavior is the only currency.', 'What did you observe users DOING, versus what did they say?', ['Avoid stated-preference traps', 'Observe real workflows', 'Test before building models'], 10, [['Research notes', '10 interviews, all hypothetical questions; 0 workflow observations']]), ('aiprod-research-woz', 'The Six-Month Model', 'Engineering wants 6 months to train a custom model for auto-triage. Product is unsure users even want auto-triage versus better manual tools.', 'What is the fastest way to resolve the uncertainty?', ['Build better manual tools instead.', 'Wizard-of-Oz test in one week: a human triages behind the interface at realistic speed and error rate. Measure completion, trust behaviors, and correction rates — then decide whether the model investment is justified.', 'Build the model; engineering is confident.', 'Survey users about auto-triage preference.'], 1, "The correct approach buys the key information for one week instead of six months: WOZ validates desirability and the UX before any model work. If users override the 'AI' constantly, you just saved half a year.", 'What is the cheapest test of the core value exchange?', ['Run Wizard-of-Oz tests', 'Validate desirability before models', 'Time-box concept validation'], 10, [['Proposal', '6-month custom model; no user validation of auto-triage concept']]), ('aiprod-research-oracle', 'The Oracle Users', "Your AI research assistant is positioned as a 'drafting copilot,' but analytics show users paste its output directly into client deliverables with zero edits. Errors have reached clients twice.", 'What is the research/UX failure?', ['The model needs to be perfect before shipping.', 'Remove the copy button.', "Mental-model mismatch: users treat it as an oracle despite 'copilot' positioning — the UI's confident tone and frictionless copy-paste taught them not to verify. Fix with provenance display, edit friction on first use, and explicit verification prompts for external-facing outputs.", 'Users are careless; add a terms-of-service warning.'], 2, "The correct approach treats zero-edit pasting as a learned behavior the product taught: every frictionless, confident, correct-looking output trained 'no need to check.' Reshaping the mental model requires UI changes (sources, confidence, verification moments), not legal text.", 'What did the product teach users about whether to verify?', ['Diagnose mental-model mismatch', 'Design for verification behavior', 'Measure trust behaviors'], 15, [['Analytics', 'Median edits per output: 0; 2 client-facing errors in 60 days']]), ('aiprod-research-novelty', 'The Launch Spike', 'Your AI feature hit 50k weekly users at launch. By week 8, it is 6k. Leadership calls it a marketing problem.', 'What do the cohorts actually say?', ['Increase ad spend to replace churned users.', 'Add gamification to bring users back.', 'The market is too small.', 'Novelty decay, not a marketing problem: AI demos spike on curiosity and collapse when the habit does not form. The fix is activation and retained-use work — faster time-to-value, better first-run, correction-rate reduction — not more top of funnel.'], 3, 'The correct approach reads the cohort curve honestly: a launch spike followed by 88% decay is the signature of novelty without habit. Pouring acquisition onto 12% retained activation multiplies waste; the leverage is in the first-run experience and the core loop.', 'What percentage of week-1 users are still doing the core action in week 8?', ['Read cohort curves honestly', 'Distinguish novelty from PMF', 'Fix activation before acquisition'], 10, [['Cohorts', 'W1: 50k, W4: 18k, W8: 6k; activation rate 11%']]), ('aiprod-research-skeptic', 'The Skeptical Veteran', "Your best interview subject is a 20-year support veteran who has watched three 'AI' tools fail. She lists exactly how each one broke trust.", 'How should the team treat this interview?', ['As the most valuable one: she is describing the trust bar — the specific failure modes your product must not repeat. Recruit more skeptics; enthusiasts tell you what is exciting, skeptics tell you what is required.', 'Discount it; she is resistant to change.', 'Avoid skeptics in research; they bias results negative.', 'Build only for the enthusiasts.'], 0, "The correct approach inverts the instinct to avoid critics: the veteran's scar tissue is a specification. Each past failure she names is a requirement your trust design must satisfy — and she represents the majority of the eventual user base.", 'Who represents your future mainstream users — the enthusiast or the veteran?', ['Recruit skeptical users', 'Treat scar tissue as specification', 'Research the trust bar'], 10, [['Interview notes', 'Veteran named 7 specific trust-breaking failures across 3 tools']]), ('aiprod-research-correction', 'The Correction Goldmine', "Support agents correct the AI's draft responses 30% of the time, but the corrections vanish — no logging, no analysis. Model quality has plateaued.", 'What research/ops move unlocks the next quality jump?', ['Hire annotators to label fresh data instead.', 'Instrument the correction pipeline: log before/after diffs, cluster them into defect themes, feed them into evals and fine-tuning with consent and PII scrubbing. A 30% correction rate is a labeled dataset being thrown away.', 'Tell agents to correct less.', 'The model has hit its ceiling; ship as-is.'], 1, 'The correct approach recognizes the corrections as the highest-value data the company owns: real-world, in-distribution, with human-verified fixes. Paid annotators cannot replicate the distribution; the pipeline turns daily work into compounding quality.', 'What is the cost of the labeled data you are currently discarding?', ['Capture correction signal', 'Build the flywheel', 'Cluster corrections into defects'], 10, [['Operations', '30% correction rate; 0 corrections logged or analyzed']]), ('aiprod-research-tribes', 'The Three User Tribes', 'Research reveals three distinct groups: autopilot fans (want full automation), copilot pragmatists (want drafts to review), and skeptics (want AI nowhere near their work). One product, one UX.', 'How do you serve all three?', ['Build for the skeptics; safety first.', 'Average the needs into one middle-ground UX.', 'Design modes, not averages: a default copilot experience with an autopilot mode for trusted workflows and a manual mode with AI fully off. Research sized the tribes; the product respects each — the average UX pleases nobody.', 'Build for the enthusiasts; skeptics will come around.'], 2, 'The correct approach refuses the average: designing for the mean user creates a product too automated for skeptics and too manual for fans. Modes let each tribe get their ideal experience while sharing the underlying capability.', 'What happens to the skeptic forced into autopilot — and the fan forced into manual review?', ['Segment by automation appetite', 'Design modes over averages', 'Respect skeptic workflows'], 10, [['Segments', 'Autopilot 25%, copilot 50%, manual-only 25% — stable across interviews']]), ('aiprod-research-access', 'The Accessibility Blind Spot', 'Your AI voice-first product tests wonderfully with the team. Launch reveals a problem: deaf users cannot use the voice interface, and screen-reader users get unstructured AI output read as a wall of text.', 'What research discipline was missing?', ['More QA testing before launch.', 'An accessibility audit after launch.', 'Disabled users are an edge case; prioritize the majority.', 'Inclusive recruitment from the start: accessibility is not a QA pass, it is a research input — disabled users in discovery reveal structural choices (voice-only input, unstructured output) that are expensive to retrofit.'], 3, 'The correct approach treats accessibility as discovery, not remediation: including disabled users in research surfaces modality assumptions early, when they are cheap to design around. Retrofitting structured output for screen readers after launch costs 10x.', 'Which product decisions assumed abilities your whole user base does not share?', ['Recruit inclusively in discovery', 'Treat accessibility as research input', 'Design multi-modal AI UX'], 10, [['Launch feedback', 'Voice-only flows unusable for deaf users; screen readers choke on unstructured output']])], icon='🔍'),)
    did = 'go-to-market'
    (std(did, 'Go-To-Market for AI Products', 'Positioning, launch strategy, distribution, and the metrics that prove GTM is working.', [('Positioning: Say What It Does, Not What It Is', ["Position on the outcome, not the technology: 'cut support handle time 40%' beats 'GPT-powered semantic copilot' — buyers buy results, not architectures", "Name the enemy: the clearest positioning contrasts with the status quo ('replace the 6-tool swivel chair') rather than listing features", 'AI-washing destroys trust: if the AI is a thin wrapper, say what it actually does — oversold AI that underdelivers poisons the whole category for you', 'One persona, one pain, one promise: the homepage speaks to a single buyer with a single urgent problem before it speaks to everyone'], 'Positioning statement:\n  For [support leaders drowning in ticket backlog]\n  who [need faster resolution without hiring],\n  [Acme Copilot] is [the AI agent]\n  that [resolves 60% of tickets autonomously],\n  unlike [chatbot widgets that deflect nothing].', "Test positioning with the 'so what' drill: read every homepage claim and ask 'so what?' until you reach a business outcome. If you cannot get there in two steps, the claim is technology in a trench coat.", ['Leading with the model name instead of the outcome', "Claiming 'AI-powered' for a rules engine with a classifier", 'Positioning to everyone — which positions to no one'], 'Write a positioning statement for an AI product you know using the template above.'), ('Launch Strategy: Sequenced, Not Big Bang', ['Lighthouse customers first: 3-5 design partners who feel the pain acutely, get white-glove onboarding, and become case studies — their logos open every later door', 'Waitlist as instrument: a waitlist is not hype, it is a prioritized interview pipeline — segment by persona and pain, onboard in cohorts, learn between each', 'Launch in waves: private alpha (friendly users, broken things OK) → public beta (positioned, instrumented) → GA (SLA, support, packaging) — each wave has exit criteria', 'The launch artifact that matters most is proof: one quantified customer story beats ten feature announcements'], 'Wave plan:\n  Alpha (4 wks): 5 design partners, weekly calls, no SLA\n  Beta (8 wks): 100 users from waitlist, usage instrumentation\n  GA: packaging + pricing live, support staffed, 2 case studies\n\nExit criteria written before each wave.', 'Resist launching to everyone at once: a big-bang launch spends your one moment of attention on a product that has not yet learned from real users. Sequenced waves convert attention into learning, then learning into proof, then proof into scale.', ['Big-bang launch with no design partners or proof', 'Waitlist as a vanity metric with no segmentation or learning loop', 'Skipping exit criteria — waves blur into permanent beta'], 'Draft exit criteria for moving an AI feature from private alpha to public beta.'), ('Distribution: Where AI Products Actually Sell', ['Product-led growth: the product IS the sales motion — free tier, viral artifacts (shared reports, public dashboards), and upgrade prompts at value moments', 'Sales-led for enterprise: AI products with compliance needs sell through champions and security reviews — arm the champion with ROI docs and a security packet', 'Marketplace and ecosystem: list where buyers already shop (cloud marketplaces, app stores) — procurement is faster when the vendor is pre-approved', 'Partnerships: agencies, consultants, and platform partners sell your product inside their services — the highest-leverage channel once you have proof'], 'Channel fit:\n  Prosumer/dev tool -> PLG + community\n  Mid-market SaaS -> PLG + inside sales assist\n  Enterprise AI -> sales-led + marketplace + partners\n\nMatch motion to buyer, not to fashion.', "Pick channels by where your buyer's trust already lives: developers trust docs and peers, executives trust peers and analysts, IT trusts procurement vehicles. One channel done well beats three done thinly — sequence them as proof accumulates.", ['PLG motion for a product that requires a security review to adopt', 'Ignoring cloud marketplaces where your buyer already has committed spend', 'Partner program before you have a repeatable sale to hand partners'], 'For one AI product, rank PLG, sales-led, marketplace, and partnerships by fit. Justify the top pick.'), ('GTM Metrics: Activation to Expansion', ['Activation: the percentage of signups reaching the magic moment (first successful AI output) within the first session — the single most predictive GTM metric', 'Time-to-value: median minutes from signup to first meaningful result — every minute of setup friction compounds into churn', 'Net revenue retention (NRR): revenue from a cohort a year later including expansion minus churn — 120%+ means the product sells itself deeper', 'CAC payback: months of gross margin to repay acquisition cost — AI products with usage-based pricing must watch this as power users concentrate cost'], 'GTM dashboard:\n  Activation (magic moment in session 1): 32% -> target 50%\n  Time-to-value: 47 min -> target <15\n  NRR: 118%\n  CAC payback: 11 mo\n\nFix activation first — it multiplies everything downstream.', 'When GTM stalls, debug the funnel in order: acquisition → activation → retention → expansion. Most AI products do not have a traffic problem; they have an activation problem wearing a traffic costume. Fix the magic moment before buying more top of funnel.', ['Optimizing acquisition while activation sits at 15%', 'Celebrating logo count while NRR bleeds below 100%', 'No instrumentation on the magic moment itself'], 'Define the magic moment and activation metric for an AI product you know.'), ('Category Creation vs Capture', ['Category creators educate the market: expensive, slow, but the winner defines the buying criteria — only attempt with venture-scale funding and a genuinely new job-to-be-done', "Category capturers ride existing demand: position against the known category ('the AI-native Zendesk') and win on the wedge — faster, cheaper, and legible to buyers", 'Most AI startups should capture, not create: buyers already budget for support software, analytics, and security — be the AI-native version, not a new line item', "The naming decision is strategic: a new category name confuses procurement ('what budget does this come from?'); a known category name accelerates it"], 'Decision test:\n  Do buyers already budget for this job? YES -> capture\n  Is the job genuinely new (no budget exists)? -> create (with funding)\n  Can you describe it in 5 words using known terms? YES -> capture\n\nClarity beats novelty in GTM.', 'If you choose creation, budget 18-24 months of education: analyst briefings, category content, and lighthouse proof. Creation without the education budget is just confusing marketing.', ['Inventing category names for a better version of existing software', "No budget line for the purchase — deals stall in 'innovation' limbo", 'Creation ambition without education funding'], 'Classify three AI products you know: category creators or capturers? Was the choice right?')], [('aiprod-gtm-position', 'The Model-Name Homepage', "Your homepage hero reads: 'Powered by the latest frontier models with RAG, agents, and chain-of-thought reasoning.' Demo requests are flat. Visitor interviews say it 'sounds like everyone else.'", 'What is the positioning fix?', ["Lead with the outcome for one persona: 'Resolve 60% of support tickets without hiring' — then prove it with a customer number. Technology belongs in the docs; the homepage sells the result.", 'Add more model names and benchmarks to stand out.', 'Redesign the hero with better visuals.', 'Lower the price and lead with that.'], 0, 'The correct approach translates technology into buyer outcomes: every AI startup claims the same stack, so the stack cannot differentiate. One persona, one pain, one quantified promise — with proof — is what earns the demo request.', 'What does the buyer get on Monday morning?', ['Position on outcomes', 'Target one persona', 'Differentiate with proof'], 10, [['Homepage', 'Hero lists model/tech terms; 0 customer proof points above the fold']]), ('aiprod-gtm-lighthouse', 'The Logo Chase', 'Sales wants to chase a Fortune 100 logo for launch. The deal needs 6 months of custom features, a dedicated team, and the product is pre-beta.', 'What is the right sequencing?', ['Delay launch until the big logo closes.', 'Decline the whale for now: 3-5 mid-market design partners in 4-8 week waves build proof faster and teach you the repeatable sale. The Fortune 100 deal customizes you into a consultancy before you have a product.', 'Take the deal — the logo is worth it.', 'Take it but charge a large professional-services fee.'], 1, "The correct approach protects the product's learnability: early whales demand customization that fragments the roadmap and consumes the team. Design partners with acute pain and fast cycles produce case studies AND product insight; whales produce slideware.", 'What will you learn from this customer that the next ten can reuse?', ['Sequence lighthouse customers', 'Resist premature whale deals', 'Optimize early GTM for learning'], 15, [['Deal terms', '6-month custom build; product still pre-beta; team of 8']]), ('aiprod-gtm-plg', 'The PLG Illusion', 'Your AI compliance product has a free tier and self-serve signup. Signups are strong but enterprise buyers — your actual revenue — all require security reviews, DPA negotiations, and procurement. Sales cycles stall at legal.', 'What distribution correction is needed?', ['Hire more salespeople and push harder.', 'Wait for buyers to finish legal on their own.', 'Dual motion: keep PLG for evaluation and champions, but build the sales-led apparatus the revenue requires — security packet, DPA templates, cloud marketplace listing (pre-approved procurement), and ROI docs that arm the champion through legal.', 'Kill the free tier; it attracts the wrong buyers.'], 2, 'The correct approach matches motion to how the money actually buys: PLG creates champions, but enterprise AI closes through procurement vehicles. The marketplace listing and pre-built security packet remove the exact friction stalling deals.', 'Where do your deals actually die — and what artifact unblocks that stage?', ['Match motion to buyer', 'Build sales-led apparatus for enterprise', 'Use marketplaces for procurement'], 10, [['Pipeline', '40% of enterprise deals stall 60+ days in legal/procurement']]), ('aiprod-gtm-proof', 'The Feature Launch Flop', 'You launched a major AI feature with a blog post, tweets, and a webinar. Traffic spiked; signups barely moved. The announcement listed capabilities.', 'What launch asset was missing?', ['More announcement channels.', 'A bigger webinar with a famous guest.', 'A launch discount.', "Proof: a quantified customer story showing the before/after ('cut triage time from 4 hours to 20 minutes at Acme'). Capability announcements inform; proof converts — especially for AI, where buyers assume demos are cherry-picked."], 3, "The correct approach recognizes that AI buyers discount vendor claims heavily — everyone has seen a cherry-picked demo. One real customer's measured outcome outweighs any feature list; launches should ship proof, not just capabilities.", 'Why would a skeptical buyer believe this announcement?', ['Launch with customer proof', 'Quantify before/after outcomes', 'Counter AI skepticism with evidence'], 10, [['Launch metrics', 'Traffic +300%, signups +4%; zero customer quotes in materials']]), ('aiprod-gtm-activation', 'The Signup Graveyard', "10,000 signups last quarter, 8% ever reached the 'first insight' moment, and most churned within a day. Marketing wants more ad spend.", 'Where is the real problem?', ['Activation, not acquisition: 92% of signups never experience the magic moment. Fix onboarding — guided first-run, sample data, time-to-value under 15 minutes — before spending another dollar on traffic. More signups just fill the graveyard faster.', 'The ads target the wrong audience.', 'The product needs more features to retain users.', 'Email the churned users with a discount.'], 0, 'The correct approach debugs the funnel in order: with 8% activation, acquisition is not the constraint. Every ad dollar amplifies a broken first-run; fixing time-to-first-value multiplies the value of all future acquisition.', 'What happens in the first 15 minutes after signup?', ['Diagnose activation before acquisition', 'Shorten time-to-value', 'Fix the magic moment first'], 15, [['Funnel', '10k signups; 8% activation; median time-to-first-value 47 min']]), ('aiprod-gtm-nrr', 'The Leaky Bucket', 'New logo growth looks great, but net revenue retention is 86% — existing accounts shrink every year. The board asks why growth feels so hard.', 'What does 86% NRR demand?', ['It is fine; new logos cover it.', 'A retention and expansion program, not more logos: interview churned accounts, fix the top cancellation drivers, build the expansion path (new teams, new modules, usage growth). At 86% NRR you must replace 14% of revenue yearly just to stand still.', 'More aggressive new-logo targets to outrun churn.', 'Discount renewals to stop the bleeding.'], 1, "The correct approach treats NRR below 100% as the company's real growth ceiling: every year starts 14% in the hole. Expansion (land-and-expand motions, new AI modules for existing accounts) plus churn root-cause work compounds; logo-chasing on a leaky bucket does not.", 'How much new revenue just replaces what walked out the door?', ['Read NRR as the growth ceiling', 'Build expansion motions', 'Fix churn drivers systematically'], 10, [['Cohort data', "NRR 86%; top churn reasons: 'never fully adopted' (41%), price (22%)"]]), ('aiprod-gtm-analyst', 'The Analyst Briefing', 'A major industry analyst firm is writing the definitive report on your AI category. You are not in the draft. Enterprise buyers cite this report in every RFP.', 'What is the right move?', ['Complain publicly about the omission.', 'Pay for a sponsored placement.', 'Engage the analyst program immediately: briefings, customer references, product demos — analyst relations is enterprise GTM infrastructure, not PR. Missing from the report means missing from shortlists you never hear about.', 'Ignore analysts; product-led growth will win.'], 2, 'The correct approach treats analyst coverage as pipeline infrastructure: enterprise buyers outsource category understanding to analysts, and absence reads as non-existence. Briefings plus reference customers earn placement; PR stunts and sponsored slots do not move the evaluation.', 'Where do your enterprise buyers learn which vendors exist?', ['Invest in analyst relations', 'Earn placement with proof', 'Treat coverage as pipeline'], 10, [['Market', 'Analyst report cited in 70% of enterprise RFPs; your company absent']])], icon='🚀'),)
    new_domains.append(mock_domain(CN))
    new_domains.append(capstone_domain(CN, 'AI Product Launch', 'a launched AI product slice: framed problem, evaluated prototype, priced packaging, and a sequenced go-to-market plan', ['Frame the problem: customer, job-to-be-done, pain quantification, and the AI 10x test', 'Build the evaluated slice: working prototype with golden-set evals and a measured baseline', 'Design the UX: trust-calibrated interface with provenance, gates, and feedback capture', 'Price it: unit economics model, tier packaging, and the free-to-paid path', 'Plan the launch: lighthouse sequence, proof assets, and GTM metrics dashboard']))
    labs += [LB('lab-aiprod-framing', 'Problem Framing Canvas', 'Frame an AI product opportunity with customer, job-to-be-done, pain math, and the 10x test.', ['Pick a workflow you know and fill the framing canvas (customer, job, today-state, pain cost)', 'Run the AI 10x test: could rules, search, or a template solve it? document the verdict', 'Write the working-backwards press release: headline, customer quote, measurable win', 'Get one skeptical user to react to the press release; record objections'], [('ls framing-canvas.md', '10x', 'framing canvas missing — complete the canvas first')], 'Problem framed with pain math and a 10x verdict. You now have a product thesis, not a demo.'), LB('lab-aiprod-rag-slice', 'Evaluated RAG Slice', 'Build a minimal RAG prototype over real documents with a golden-set eval and measured baseline.', ['Ingest 50-200 real documents; build chunking + embedding + retrieval', 'Assemble 30 golden Q&A pairs with human-verified answers and source spans', 'Implement groundedness scoring: every claim must cite a retrieved span', 'Run the baseline, record it, and document the top 3 failure modes'], [('ls rag-eval/baseline.json', 'grounded', 'eval baseline missing — run the golden set first')], 'RAG slice built with a pinned baseline and known failure modes. Quality is now measurable.')]
    d2, l2 = build_aiprod2()
